import * as T from './assets/three.module.js';
export function setupSignalEffects(shell){
 const view=shell.querySelector('.workspace-view'),panel=document.createElement('div');panel.className='signal-instruments';panel.innerHTML='<div class="signal-phase-strip"><span data-signal-phase="0">01 EMIT</span><span data-signal-phase="1">02 OUTBOUND</span><span data-signal-phase="2">03 RESPONSE</span><span data-signal-phase="3">04 RETURN</span><span data-signal-phase="4">05 RECEIVED</span></div><div class="signal-progress"><i></i></div><canvas id="signal-waveform" width="900" height="80" aria-label="Illustrative signal waveform"></canvas><div class="signal-log" role="log" aria-label="Transmission event log"></div>';view.append(panel);
 const knobs=document.createElement('div');knobs.className='signal-knobs';knobs.innerHTML='<label>Wavefront rendering<select id="signal-style"><option value="wave">Wavefronts + packet train</option><option value="beam">Focused beam</option><option value="minimal">Precision marker</option></select></label><label>Signal intensity<input id="signal-intensity" type="range" min=".25" max="1.5" step=".05" value=".8"></label><label><input id="signal-autopilot" type="checkbox"> Cinematic orbit</label>';shell.querySelector('.workspace-config').prepend(knobs);const styleControl=knobs.querySelector('select'),intensityControl=knobs.querySelector('input[type=range]'),progressBar=panel.querySelector('.signal-progress i');const log=panel.querySelector('.signal-log'),canvas=panel.querySelector('canvas'),ctx=canvas.getContext('2d');let id=0,received=0,phase=0,clock=0;
 const glowCanvas=document.createElement('canvas');glowCanvas.width=glowCanvas.height=64;const c=glowCanvas.getContext('2d'),g=c.createRadialGradient(32,32,0,32,32,32);g.addColorStop(0,'#fff');g.addColorStop(.12,'#fff9');g.addColorStop(1,'#fff0');c.fillStyle=g;c.fillRect(0,0,64,64);const glow=new T.CanvasTexture(glowCanvas);
 function event(label){const row=document.createElement('div');row.textContent=String(++id).padStart(3,'0')+' / '+label;log.prepend(row);while(log.children.length>6)log.lastChild.remove()}
 function create(packet){const group=new T.Group();packet.mesh.add(group);const halo=new T.Sprite(new T.SpriteMaterial({map:glow,color:0xffce87,transparent:true,blending:T.AdditiveBlending,depthWrite:false}));halo.scale.setScalar(.8);group.add(halo);const rings=[];for(let i=0;i<4;i++){const ring=new T.Mesh(new T.RingGeometry(.25,.265,64),new T.MeshBasicMaterial({color:0xeac28a,transparent:true,opacity:.6,side:T.DoubleSide,blending:T.AdditiveBlending,depthWrite:false}));group.add(ring);rings.push(ring)}const pos=new Float32Array(36*3),geo=new T.BufferGeometry();geo.setAttribute('position',new T.BufferAttribute(pos,3));const tail=new T.Line(geo,new T.LineBasicMaterial({color:0xdcb47c,transparent:true,opacity:.6,blending:T.AdditiveBlending,depthWrite:false}));group.add(tail);const beam=new T.Mesh(new T.CylinderGeometry(.035,.035,packet.a.distanceTo(packet.b),16,1,true),new T.MeshBasicMaterial({color:0xf6c78a,transparent:true,opacity:.2,blending:T.AdditiveBlending,depthWrite:false,side:T.DoubleSide}));group.add(beam);packet.effect={group,rings,halo,tail,pos,beam,direction:packet.b.clone().sub(packet.a).normalize()};event('EMISSION / PACKET RELEASED');}
 function update(packet){const fx=packet.effect;if(!fx)return;const f=packet.elapsed/packet.seconds,returning=f>1,head=packet.mesh.position,dir=fx.direction.clone().multiplyScalar(returning?-1:1),style=styleControl.value,intensity=+intensityControl.value;phase=f>=2?4:f>=1.9?3:f>=1?2:1;const color=returning?0xa9dfce:0xffce87;fx.halo.material.color.setHex(color);fx.halo.material.opacity=intensity;fx.halo.scale.setScalar(style==='beam'?.6:.85);packet.mesh.material.color.setHex(color);
  fx.beam.visible=style==='beam';fx.beam.position.copy(packet.a).add(packet.b).multiplyScalar(.5).sub(head);fx.beam.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),packet.b.clone().sub(packet.a).normalize());fx.beam.material.opacity=intensity*.2;fx.beam.material.color.setHex(color);fx.rings.forEach((ring,i)=>{ring.visible=style==='wave';ring.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),dir);ring.position.copy(dir).multiplyScalar(-i*.3);ring.scale.setScalar(.5+i*.55);ring.material.color.setHex(color);ring.material.opacity=intensity*(1-i*.2)*.5;});fx.tail.visible=style!=='minimal';fx.tail.material.color.setHex(color);for(let i=0;i<36;i++){const q=Math.max(0,f-i*.004),t=q<=1?q:2-q,k=Math.max(0,Math.min(1,t));fx.pos[i*3]=packet.a.x+(packet.b.x-packet.a.x)*k-head.x;fx.pos[i*3+1]=packet.a.y+(packet.b.y-packet.a.y)*k-head.y;fx.pos[i*3+2]=packet.a.z+(packet.b.z-packet.a.z)*k-head.z}fx.tail.geometry.attributes.position.needsUpdate=true;progressBar.style.width=Math.min(100,f/2*100)+'%';if(f>=1&&!packet.responseLogged){packet.responseLogged=true;event('ARRIVAL / RESPONSE WAVEFRONT')}if(f>=2&&!packet.receiveLogged){packet.receiveLogged=true;received++;event('RECEIVED / '+received+' ROUND TRIPS COMPLETE')}
 }
 function dispose(packet){const fx=packet.effect;if(!fx)return;fx.group.traverse(o=>{o.geometry?.dispose();o.material?.dispose()});fx.group.removeFromParent();packet.effect=null;}
 function tick(dt,time,mode,activeCount){clock+=dt;panel.hidden=knobs.hidden=mode!=='ping';if(mode!=='ping')return;if(clock<1/24&&time>0)return;clock=0;panel.querySelectorAll('[data-signal-phase]').forEach(el=>el.classList.toggle('active',+el.dataset.signalPhase===phase));ctx.clearRect(0,0,900,80);ctx.strokeStyle='#33423f';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,40);ctx.lineTo(900,40);ctx.stroke();ctx.strokeStyle=phase>=2?'#a9dfce':'#dfbd87';ctx.lineWidth=1.5;ctx.beginPath();for(let i=0;i<=900;i++){const env=activeCount?Math.exp(-Math.pow((i/900-((time*.3)%1))/.18,2)):0,x=i,y=40+Math.sin(i*.15-time*20)*env*27;(i?ctx.lineTo(x,y):ctx.moveTo(x,y))}ctx.stroke();}
 return {create,update,dispose,tick,get autopilot(){return knobs.querySelector('#signal-autopilot').checked}};
}
